              <MenuItem icon={<Keyboard size={16} />} shortcut="?" onClick={() => { close(); dispatch({ type: 'ui', patch: { shortcutsOpen: true } }) }}>Keyboard shortcuts</MenuItem>
              <MenuItem icon={<CheckCheck size={16} />} onClick={() => { close(); toast('Local account, nothing to sign out of. Your mail stays on this device.') }}>Account status</MenuItem>
