      title={title}
      aria-label={title}
      onMouseDown={(e) => e.preventDefault()}
      onClick={onAct}
      className="hidden h-7 w-7 items-center justify-center rounded text-ink-2 hover:bg-hover hover:text-ink md:inline-flex"
    >
      {children}
    </button>
  )
}
